struct Render final:IRenderBackend {std::vector<DrawCall> draws;bool initialize(const RenderConfig&,IWindowBackend*,std::string*)override{return true;}void shutdown()override{}RenderCapabilities capabilities()const override{return {};}bool upload_vertices(const Vertex*,std::size_t)override{return true;}bool upload_matrix(u32,const f32*)override{return true;}bool upload_texture(u32,const TextureDesc&)override{return true;}void begin_frame(const FrameDesc&)override{draws.clear();}void submit(const DrawCall& d)override{draws.push_back(d);}void end_frame()override{}void present()override{}};
